INSERT INTO manager_profiles VALUES(1,'philosophy','에메리의 축은 세 가지다. ⑴ 짧은 빌드업으로 상대 1선을 넘긴 뒤 하프스페이스에서 수적 우위를 만드는 포지셔널 전진 — 롱볼이 아니라 구조로 전진한다. ⑵ 수비는 강한 전방 압박이 아니라 미드블록 두 줄 4(뱅크): 와이드 미드필더까지 두 번째 줄로 복귀시켜 중앙 진입로를 닫고, 탈취 후 빠른 전환. ⑶ 상대·스코어에 따른 라인 조절이 체계적이다 — 기준 52, 리드 시 45(딥블록 전환), 약팀 상대 67(하이라인). 좌우는 비대칭: 풀백은 한 명씩만 전진(C2 제약)하고 10번에게는 로밍 자유를 준다.','docs/10 · obs#4·#27(C2)·#89(뱅크)·#101(rest-defense) · team_tactic_setups optimal 계열 실측 도출',NULL,'HIGH — 25/26 전수 실측 기반','2026-08-11');
INSERT INTO manager_profiles VALUES(1,'traits','풀백 한 명씩만 전진(C2), 우측 와이드는 뱅크 복귀형(wm_widemid/Support), 10번은 자유 로밍. 리드 시 딥블록 전환(optimal:lead, 라인 45).','obs#89·#106·#110 · docs/20 Wide Mid 리워크',NULL,'HIGH','2026-08-11');
INSERT INTO manager_profiles VALUES(1,'formation','4-2-3-1 Wide 고정 — 시즌 내 포메이션 불변이 실측으로 확인됨. 국면 변형은 라인·역할로만.','team_match_stats formation_v · docs/10',NULL,'HIGH','2026-08-11');
INSERT INTO manager_profiles VALUES(2,'philosophy','레버쿠젠 원형의 이식 — 백3 빌드업과 윙백 폭 독점, 하프스페이스 2×10번. 25/26 첼시 전술과 무관하며(규칙 7) 26/27 처방은 블루프린트 단계다.','docs/11 · obs#37~62 · team_tactic_setups(CHE, projected 3-4-2-1)',NULL,'MEDIUM — 개막 전 처방','2026-08-11');
INSERT INTO manager_profiles VALUES(2,'traits','카이세도 하강 빌드업(백라인 옆 압박 유인), 리스 제임스 하이브리드 RDM(창조 축), 팔머 우측 포켓. 수비 국면 5-4-1 참조형.','obs#44·#46·#102 · CHE 처방 프리셋 주석(archive/v1)',NULL,'MEDIUM','2026-08-11');
INSERT INTO manager_profiles VALUES(2,'formation',unistr('【기존 축 보강 — 첼시 부임 후 실제 근거】 프리시즌 5경기 내내 기본은 4-2-3-1이었고, 백3는 밀란전(8/8)에서 국면적으로 등장했다. 밀란전 첼시 공식 선발 표기는 산체스 — 아체암퐁·포파나·하토·팔레스트라 — 라비아·카이세도 — 팔머·주앙 페드루·네투 — 웰벡이며 공식 기재상 4명 백라인이다(분석 매체는 ''구간 백3''로 서술 — 즉 점유 국면 변형이지 선발 백3가 아니다). 결과 3-0 승, 2026 인도네시아 슈퍼컵 우승. 투어 전적: 웨스턴시드니 6-4 승 → 토트넘 1-2 패 → 유벤투스 0-1 패 → 밀란 3-0 승 → 조호르. 좌측 백3 후보였던 하토가 백4의 CB로, 팔레스트라가 좌측 풀백으로 배치된 점이 우리 처방(하토 LCB·팔레스트라 RWB)과 어긋난다. 차바리아 영입이 백3 전환의 촉매로 지목됐다. ⚠️ 제임스·엔소는 월드컵 후 휴가로 투어 대부분 결장 — 프리시즌 배치를 최종 서열로 읽으면 안 된다.\u000a\u000a⚙️ **게임 구현**: 기본 포메이션을 3-4-2-1(5-4-1)로 단일 고정한 현 처방의 근거가 약해졌다 — 프리시즌 5경기 기본형은 4-2-3-1이고 알론소 본인도 가변을 선언했다. 개막 후 실측 전까지는 3-4-2-1을 ''가설 A'', 4-2-3-1을 ''가설 B''로 병기하는 편이 정직하다.'),'첼시 공식 매치리포트 Chelsea 3-0 Milan(2026-08-08) · OneFootball(2026-08-08, 알론소 발언) · roundtable.io 프리시즌 일정·결과 정리 · The Chelsea Chronicle ''Chelsea predicted XI vs AC Milan: Alonso trials new formation''(2026-08)',NULL,'MEDIUM — 선발 명단은 구단 공식(1티어)이나 프리시즌이고 주전 2명 결장. obs#60(웨스턴시드니전 4-2-3-1 백4)의 결론이 투어 전체로 확장 확인됐다는 점이 새 사실이며, obs#153(백3 구조 부분 지지)과 함께 읽어야 한다. 첼시 공식전 표본은 여전히 0(첫 경기 8/24 풀럼).','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'philosophy','고강도 압박과 수직 전환 — 본머스 실측이 원형(PPDA 정본표는 docs/12). 26/27 리버풀 이식은 개막 후 실측 대기.','docs/12 · obs#80(PPDA 정의 차이)',NULL,'MEDIUM — 이식 검증 전','2026-08-11');
INSERT INTO manager_profiles VALUES(3,'traits','인버티드 RB(프림퐁 fb_inverted 성향 실측), 살라 우측 인사이드, 비르츠 하프윙어 10번. ⚠️ 25/26 실측은 전임 체제 — 개인 성향 기준선으로만.','LIV measured 12명 · 규칙 7',NULL,'MEDIUM','2026-08-11');
INSERT INTO manager_profiles VALUES(1,'implementation','게임 구현(FC26 설정 시트가 이 번역의 결과다): ⑴ 짧은 빌드업 → 팀 세팅 Short Passing + GK gk_goalkeeper/Defend(스위퍼 아님 — 실측 .961) + 양 CB cb_bpd(볼 플레잉). ⑵ 미드블록 뱅크 → 수비 Balanced + 라인 52 + 우측 와이드 wm_widemid/Support(EA 정의 "복귀해 수비 지원" — 뱅크 복귀의 게임 대응) + 더블 피벗 dm_holding(Roaming/Defend 분담). ⑶ 라인 조절 → 상황 프리셋: 리드 시 Deep 45, 약팀 High 67 (팀 세팅만 바꾸고 역할 유지). ⑷ C2 풀백 비대칭 → LB fb_att_wb/Support(전진) vs RB fb_wingback/Balanced(잔류) — 같은 역할을 양쪽에 주면 C2가 붕괴한다(obs#110의 Δ.0101 지불 근거). ⑸ 자유 10번 → cam_playmaker/Roaming(부엔디아·맥긴) 또는 cam_halfwinger(만잠비). ⑹ 한계: 압박 강도·온더볼 창조성은 역할 커널 밖 — PlayStyles와 게임 AI가 담당(게임 시스템 페이지 참조).','FC26 설정 시트(fc26:opt) · obs#89·#106·#110 · docs/20 ④',NULL,'HIGH — 25/26 전수 실측에서 도출된 처방','2026-08-11');
INSERT INTO manager_profiles VALUES(2,'implementation','게임 구현: ⑴ 백3 빌드업 → 3-4-2-1 + 전 CB cb_bpd/Aggressive + Short Passing. ⑵ 윙백 폭 독점 → RB 구스토 fb_att_wb/Support(폭 공급자), LB는 인선 공백(영입 대기). ⑶ 하강 피벗 → 카이세도 dm_dlp/Roaming(백라인 옆 압박 유인), 리스 제임스 dm_dlp/Build-Up(창조 축 — Δ.001 동률에서 역할 유지). ⑷ 2×10번 → 로저스 wm_insidefwd(안으로), 팔머 wm_wideplm/Attack(우측 포켓). ⑸ 내려오는 9번 → 주앙 페드루 st_false9/Build-Up.','v1 CHE_PROJ 처방(archive/v1 주석) · obs#44·#46·#59·#102',NULL,'MEDIUM — 개막 전 블루프린트','2026-08-11');
INSERT INTO manager_profiles VALUES(3,'implementation','게임 구현(잠정): 이라올라 처방이 아직 없어 25/26 실측 최근접으로 임시 배치 — 알리송 GK/Defend, 반다이크·코나테 cb_bpd, 프림퐁 인버티드 성향은 fb_att_wb로 근사, 비르츠 cam_halfwinger, 살라 wm_winger/Attack. 팀 세팅은 방향성만(High·라인 64). ⚠️ 고압박 재현은 FC26 Team Press 너프로 구조적 한계 — 개막 실측 후 전면 재산출 예정.','LIV measured 12명 · game_system_changes(Team Press)',NULL,'LOW — 잠정','2026-08-11');
INSERT INTO manager_profiles VALUES(1,'buildup','저빌드업: 비대칭 4-2-2-2 — 좌윙을 비우고 GK를 참여시켜 수적 우위로 압박 돌파. 고빌드업: 3-2-5로 중앙 밀집(전진과 역압박 조건을 겸함). 콘사 RB 기용 시 백3 변환. 게임 구현: Short Passing + 볼플레잉 CB + GK Defend(스위퍼 아님 — 참여는 패스 옵션 수준).','obs#146 (the-footballanalyst·PL공식) — C2 비대칭·중앙 밀집이 실측 파생 결론과 정합',NULL,'MEDIUM-HIGH — 외부 분석 다수 수렴, 팀 실측 대조 부분','2026-08-11');
INSERT INTO manager_profiles VALUES(1,'pressing',unistr('미드블록이 기본이되 라인은 높다(하이라인+컴팩트 블록 하이브리드) — 두 줄 4로 중앙을 닫고 측면으로 유도. 상대별 강도 조절: 약팀 상대 PPDA 4.99까지 공격적(우리 vs-weak High 67 처방과 정합). 게임 구현: Balanced 기본 + 상황 프리셋으로 High/Deep 전환.\u000a\u000a[2026-08-12 보강 — 진폭 상단 최초 확보] 25/26 PPDA 평균 **9.88**, 진폭은 **vs 울버햄튼 4.99**(초공격적) ~ **vs 리버풀 20.43**(초보수적)이다. 종전 기록은 하단(4.99 계열)만 갖고 있었다. 상단 20.43은 `optimal:vs-strong`·`lead` 프리셋(라인 45 딥블록)의 **첫 외부 교차 근거**다. 함께 확인된 것: 25/26 12월 말 기준 **역습 실점 0**.'),'obs#146 · optimal:vs-weak 실측 도출과 교차 확인 ; [2026-08-12] Total Football Analysis 데이터 분석(Mustapha Hassan, 2026-02-27) ; The Mastermind Site(2025-12-29)',NULL,'MEDIUM-HIGH ; ⚠️ [2026-08-12] 외부 수집이 PPDA **9.88을 독립적으로 재현**했다 — 이는 obs#28의 9.88을 지지하고, HANDOFF에 남아 있던 "9.88 폐기·대표값 12.3/12.45" 메모와 어긋난다. **산출사 고정 없이 절대값을 비교하지 말라는 obs#71 경고가 이 불일치의 설명일 가능성이 높다**(Wyscout vs Opta 차이). 정본은 docs/12이며 다음 세션에서 산출사를 명시해 정리할 것. ⚠️ 두 소스 모두 2티어이고 시즌 중간 스냅샷이라 종료 시점 값은 미확인.','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'buildup','3-2-5 빌드업(백3+더블피벗 7인 후방 — 수적 우위) 또는 2-3-5 가변(RCB 전진). "tac-tac-tac" 짧은 리듬 패스 — 점유 자체가 목적이 아니라 상대 결정 강요. 게임 구현: Short Passing + cb_bpd 전원 + 카이세도 하강(dm_dlp/Roaming).','obs#146 (soccertutor·ACE Lab)',NULL,'MEDIUM — 레버쿠젠 원형, 첼시 이식 검증 전','2026-08-11');
INSERT INTO manager_profiles VALUES(2,'rest_defense','⚠️ 구조적 약점: 박스 미드필드 중앙에서 볼 상실 시 직선 역습에 취약 — 기술 규율 요구가 극단적으로 높다. 게임 구현 시 더블피벗 중 한 명은 Defend 계열 포커스로 보험 검토.','obs#146 (managingmadrid)',NULL,'MEDIUM','2026-08-11');
INSERT INTO manager_profiles VALUES(3,'pressing','하이브리드 프레스 — 존 수비로 시작해 트리거 발동 시 전면 맨투맨 전환, 터치라인을 추가 수비수로 쓰는 측면 압축. 목적은 공격: 파이널서드 탈취(리그 3위)→즉시 슛. ⚠️ FC26 Team Press 수비진영 너프로 트리거식 재현 불가 — High 라인+Aggressive 근사가 상한.','obs#146 (thisisanfield·PL공식)',NULL,'MEDIUM-HIGH — 본머스 실측 뒷받침','2026-08-11');
INSERT INTO manager_profiles VALUES(3,'situational','⚠️ 지배 국면 리스크: 55%+ 점유 시 1승 13경기 vs 55% 미만 12승 8무 — 언더독 구조가 슈퍼클럽에서 재현될지가 26/27 최대 검증 과제. 수직성(1.95m/s 최속·2.98패스/시퀀스)은 게임에서 Counter 빌드업 스타일 검토 근거.','obs#146',NULL,'MEDIUM-HIGH — 정량 근거 있음(원값 미수집)','2026-08-11');
INSERT INTO manager_profiles VALUES(1,'set_pieces',unistr('세트피스는 빌라의 독립된 득점 부문이고, 담당자는 감독이 아니라 전담 코치 오스틴 맥피(Austin MacPhee, 2021-08 부임 — 스미스·에머리 세 감독을 거쳐 잔류)다. 25/26 시즌 전 대회 세트피스 18골로 팀 총득점의 32%를 차지했다(24/25는 리그 13골·리그 1위, 세트피스 xG 13.1로 아스널에 이어 2위). 공격 코너의 핵심 원리는 ''수비수에게 양자택일을 강요하는 것''이다 — 숏코너 지원을 위해 니어포스트 수비수를 끌어내 그 구역을 비우고, 박스 외곽 대기 선수들끼리 역할을 교환·동조 이동해 마킹 기준을 흐린 뒤 늦게 도착하는 러너가 빈 니어포스트로 들어간다. 상대 수비 방식(첼시·레스터·에버턴·브라이턴 사례)마다 변형을 따로 준비하는 대회 단위 설계다. 에메리 본인은 맥피의 창의성을 ''필수적(vital)''이라 표현하고 세트피스를 ''많이 이야기하는 주제''라고 말한다. 반면 세트피스 **수비**에 대한 공개 분석은 사실상 없다(우리 obs#113의 ''정량 판정 불가''와 같은 공백).\u000a\u000a⚙️ **게임 구현**: FC26에서 세트피스는 팀 세팅이 아니라 키커·타겟 지정 층이다: 코너 키커에 왼발·오른발을 나눠 인·아웃스윙 선택지를 확보하고, 세트피스 시 박스 침투 지정을 장신 CB(밍스·시세·파우) + 늦게 들어오는 10번에 걸어라. 다만 게임의 세트피스 모델은 ''수비 양자택일 강요'' 같은 설계를 재현하지 못하므로, 이 축은 역할 처방(prescriptions)이 아니라 세트피스 담당자 지정 수준에서만 반영한다.'),'Total Football Analysis, ''Unai Emery & Austin MacPhee Set-Piece Tactics At Aston Villa''(2025-06-09) https://totalfootballanalysis.com/set-piece-analysis/austin-macphee-set-piece-tactics-aston-villa-tactical-analysis — 24/25 리그 세트피스 13골(1위)·xG 13.1(2위)·총득점 41골 중 32%. Sport Witness(2026-06-06, 포르투갈 A Bola 인용) https://sportwitness.co.uk/set-piece-success-at-aston-villa-earns-coach-spotlight-during-world-cup-preparations/ — 25/26 전 대회 세트피스 18골 = 총득점의 32%. Read Aston Villa(2026-04-18) https://readastonvilla.com/2026/04/18/revealed-the-secret-behind-aston-villas-set-piece-masterclass-as-unai-emery-praises-genius-austin-macphee/ — 에메리의 맥피 평가 인용.',NULL,'MEDIUM. 수치는 1~2티어(TFA·A Bola 인용)지만 25/26 18골 수치는 2차 인용이라 원자료 미확인. ⚠️ **우리 실측과 충돌한다** — obs#112는 ''빌라 세트피스는 설계된 무기가 아니라 측면 공격의 부산물''이라 판정했다(코너 수 ~ 크로스 볼륨 r=+0.712, 코너 수 ~ xG r=+0.261). 즉 우리 실측은 ''코너가 늘어도 코너발 위협은 별로 안 는다''를, 외부 소스는 ''전환율이 리그 최상위''를 말한다. 둘은 양립 가능하다(빈도 상관 ≠ 전환 효율). 판단: **빈도 축의 obs#112는 유지하되, 전환 효율 축은 우리가 측정한 적이 없다**는 결손을 명시해야 한다. 루틴 서술은 24/25 경기 기준(TFA 2025-06)이라 25/26 적용은 원리 수준으로만.','2026-08-12');
INSERT INTO manager_profiles VALUES(1,'rest_defense',unistr('에메리의 잔류 수비는 ''숫자를 남기는 것''이 아니라 ''앞으로 나가는 인원을 애초에 제한하는 것''이다. 빌드업 기본은 4-2(백4 + 더블 피벗)이고, 여기에 GK 마르티네스를 참여시켜 5-2를 만들어 상대 맨투맨 압박에도 1선에서 +1을 유지한다 — 즉 전진 국면에서도 후방에 항상 6~7명 상당의 구조가 남는다. 풀백은 한 번에 한 명만 전진하고(우리 C2 제약과 동일), 피벗 두 명(카마라·오나나)은 그 전진을 허용하기 위해 자리를 지키는 것이 1차 임무다. 그 대가는 명시적이다 — ''뒤에 인원을 많이 두면 전진 인원이 줄어든다''. 성과 지표: 25/26 12월 말 기준 빌라는 ''역습 실점(counter attacking goal)''으로 분류된 실점이 **0**이었다. 볼을 잃으면 즉시 압박이 아니라 두 줄 4로 복귀해 중앙을 닫는 쪽이고, 되찾은 뒤 왓킨스·로저스를 즉시 출구로 쓴다.\u000a\u000a⚙️ **게임 구현**: 게임 세팅으로는 ⑴ 팀 세팅에 낮은 오버랩 성향(풀백 동시 전진 금지) — 이미 LB fb_att_wb/Support vs RB fb_wingback/Balanced 비대칭으로 구현됨, ⑵ 더블 피벗 둘 다 dm_holding 계열 유지(하나라도 전진형 롤로 바꾸면 잔류 구조가 무너진다), ⑶ 수비 세팅은 Balanced·태클 Conservative 쪽(몸을 던지지 않는 수비). GK는 Defend 유지 — 5-2는 패스 옵션이지 스위퍼가 아니다.'),'The Mastermind Site, ''Unai Emery – Aston Villa – Tactical Analysis – 2025-26 Edition''(2025-12-29) https://themastermindsite.com/2025/12/29/unai-emery-aston-villa-tactical-analysis-2025-26-edition/ — ''역습 실점 0'', ''뒤에 인원을 많이 두면 전진력이 제한된다'', ''몸을 던지는 태클을 하지 않는다'', 카마라·오나나가 안정적으로 버텨 풀백 전진을 허용. Total Football Analysis 데이터 분석(Mustapha Hassan, 2026-02-27) https://totalfootballanalysis.com/data-analysis/unai-emery-tactics-aston-villa-2025-2026-data-analysis — 빌드업 4-2 기반, GK 참여로 5-2, 경기당 415패스·84.42% 성공. 취약점: 맨시티전 위험지역 볼로스트 30회(대부분 좌측).',NULL,'MEDIUM-HIGH. 2티어(전술 블로그·분석 매체) 다수 수렴, 우리 실측 파생 결론(C2 비대칭·뱅크 복귀·obs#101의 ''rest-defense 칸은 저점유 국면 기준이 맞다'')과 방향 일치. ''역습 실점 0''은 2025-12 시점 스냅샷이라 시즌 종료 시점 값은 미확인. GK 참여 서술은 우리 obs#154(비조/마르티네스 gk_goalkeeper/Defend 유지, 스위퍼 아님)와 긴장 관계 — 외부는 ''5-2를 만드는 참여''라 하지만 이는 후방 패스 옵션이지 전진 스위핑이 아니므로 obs#154 결론을 뒤집지 않는다.','2026-08-12');
INSERT INTO manager_profiles VALUES(1,'situational',unistr('상대별 조절이 에메리 체제의 가장 뚜렷한 변수이고, 그 폭은 리그 최상위권이다. 25/26 빌라 평균 PPDA는 9.88인데, 울버햄프턴전 **4.99**(초공격적)에서 리버풀전 **20.43**(초보수적)까지 벌어진다 — 같은 팀이 아니라고 봐야 할 정도의 진폭이다. 유럽 원정에서도 같다: PSG 원정에서 평균 수비 액션 지점이 골대에서 30.9m(딥블록)였던 반면 홈에서는 50m로 20m 전진했고, PSG 진영 압박 횟수는 36 → 161, 상대 진영 탈취는 6 → 34로 뛰었다. 수비 국면 형태 변화도 정형화돼 있다 — 4-2-3-1이 수비 시 10번이 스트라이커 옆으로 올라와 4-4-2 두 줄로 바뀐다(포메이션 변경이 아니라 국면 변형). 25/26 시즌 자체가 상황 대응의 사례다: 리그 4경기 무득점·40슈팅 xG 3.07의 최악 출발(10번이 너무 낮게 서고 스트라이커가 고립) 이후, 10번 라인을 올리고 중거리 슈팅을 의도적 무기로 편입(15경기 박스 밖 9골 = 리그 1위)해 12월 11연승·상위권 복귀로 반전했다.\u000a\u000a⚙️ **게임 구현**: 이미 있는 상황 프리셋(lead 45 / vs-weak 67 / base 52)의 근거를 강화한다. 추가 제안: 강팀 원정용 프리셋을 별도로 두고 라인 40~45 + 압박 Conservative로, 강팀 홈용은 라인 60+ 압박 Balanced로 분리하라 — PSG 홈/원정 20m 차이가 그 근거다. 단 역할(role)은 프리셋 간 고정한다(불변규칙: 팀 세팅만 바꾼다).'),'Total Football Analysis 데이터 분석(Mustapha Hassan, 2026-02-27) https://totalfootballanalysis.com/data-analysis/unai-emery-tactics-aston-villa-2025-2026-data-analysis — PPDA 9.88(상대 10.68), vs 울브스 4.99 / vs 리버풀 20.43, 개막 4경기 40슛 3.07xG, 박스 밖 9골(15경기·리그 1위, 원거리 슈팅 71/174). UEFA 전술 분석(2025 PSG 8강 2연전, 매체 재인용) — 원정 평균 수비 액션 30.9m vs 홈 50m, 상대 진영 압박 36→161·탈취 6→34. The Mastermind Site(2025-12-29) — 수비 시 4-4-2 전환, 11연승 시점 서술. TFA 팀 분석(Gillian Kasirye, 2025-10-02) https://totalfootballanalysis.com/team-analysis/aston-villa-2025-2026-premier-league-struggles-team-analysis-tactics — 초반 부진 원인(왓킨스 고립, 디뉴·캐시가 폭과 안정성을 동시에 못 냄, 오나나 햄스트링 이탈로 맥긴이 스크리너 대역).',NULL,'MEDIUM-HIGH. PPDA 진폭은 1티어급 수치이고 우리 pressing 축의 ''약팀 상대 4.99''와 **동일 출처로 이미 정합 확인됨**. vs 리버풀 20.43은 새 값 — 우리 optimal:vs-strong / lead 계열 프리셋(라인 45 딥블록)의 외부 교차 근거가 된다. PSG 수치는 2025년(24/25 CL 8강) 자료로 **직전 시즌 체제**임을 명시. 우리 실측(4-2-3-1 고정)과 4-4-2 서술은 충돌이 아니다 — 수비 국면 변형이며 obs#153의 ''틀린 것은 관찰이 아니라 역할 이름''과 같은 층위.','2026-08-12');
INSERT INTO manager_profiles VALUES(1,'role_demands',unistr('에메리가 요구하는 것은 포지션이 아니라 국면별 임무의 목록이고, 그 전달 수단은 개인별 영상이다. 구체 임무: ⑴ **10번** — 수비 시 스트라이커 옆으로 올라와 1차 압박(4-4-2 앞줄), 공격 시 라인 사이로 내려와 받아 나르는 ''주머니'' 역할(부엔디아·로저스). 25/26 초반 부진의 진단이 ''10번이 너무 낮게 섰다''는 것이었을 만큼 이 높이 자체가 조절 대상이다. ⑵ **풀백** — GK 배급을 받아 라인을 따라 빠르게 붙이고, 전진은 한 번에 한 쪽만. 마첸은 하프스페이스로 침투하는 유형(로저스의 안쪽 이동과 짝), 캐시는 수비 기여형(25/26 리그 28선발·수비 기여 154회). ⑶ **더블 피벗** — 자리 유지가 1차 임무이고 그 대가로 풀백 전진이 성립한다. 카마라만 기회가 나면 길게 전진한다. ⑷ **센터백** — 공격적 압박이 아니라 조화로운 이동·컴팩트 유지, 무리한 태클 금지. ⑸ **와이드** — 맥긴·로저스는 안쪽으로 들어오고(로저스는 오른발 컷인 후 중거리), 폭은 풀백이 댄다. ⑹ **스트라이커** — 왓킨스는 좌우로 흘러다니며 전환 시 즉시 출구. 인선 원칙도 여기서 나온다: 순수 기교·속도보다 **지시를 이행하고 구조 안에서 판단하는 선수**를 선호한다는 평가가 반복된다.\u000a\u000a⚙️ **게임 구현**: ⑴ 10번의 수비 시 전진은 FC26에서 역할이 아니라 팀 압박 세팅이 담당한다 — cam_playmaker/Roaming 유지하되 압박 세팅을 Balanced 이상으로 두면 앞줄 합류가 나온다. ⑵ 피벗 두 칸은 ''자리 지키기''가 임무이므로 dm_holding/dm_dlp 조합 유지가 원칙과 정확히 일치. ⑶ 캐시 RB는 수비 기여형 — 현 fb_wingback/Balanced보다 보수적인 방향의 근거가 되나, 커널 판정 없이 바꾸지 말 것. ⑷ 맥긴/로저스는 위치가 아니라 PlayStyles(컷인 후 슈팅)로 재현하는 층이다.'),'The Mastermind Site(2025-12-29) https://themastermindsite.com/2025/12/29/unai-emery-aston-villa-tactical-analysis-2025-26-edition/ — 10번의 4-4-2 전진, ''마첸은 하프스페이스로 전진 침투를 즐긴다'', ''카마라와 오나나가 안정적으로 버틴다'', 왓킨스 ''좌우로 흘러다닌다'', 로저스 ''오른발로 컷인''. TFA 팀 분석(2025-10-02) — 왓킨스 고립·10번 저위치 진단, 오나나 이탈 시 맥긴은 ''박스투박스지 스크리너가 아니다''. TFA 데이터 분석(2026-02-27) — ''artificial transition''(상대 압박을 자기 진영으로 유인한 뒤 수직 전진), ''pausa''. Azat.tv(2026-04-01) https://azat.tv/en/unai-emery-matty-cash-tactical-transformation/ — 캐시 시즌 수비 기여 154회·리그 28선발, 개인 영상 분석이 변화의 계기. Coach Notes / Nacsport(에메리 인터뷰) — 개인별 영상으로 역할을 명시적 언어로 전달, 2021 EL 결승 전 맨유 17경기 분석. ⚠️ 3티어(블로그·잡지형) 비중 있음.',NULL,'MEDIUM. 개별 임무 서술은 2~3티어이고, 상당수가 우리 실측과 **이미 정합**이다(10번 로밍·풀백 C2·피벗 잔류·왓킨스 좌우 이동). 새로 얻은 것은 ⑴ 10번의 수비 시 전진(4-4-2 앞줄) ⑵ 25/26 초반 ''10번이 낮았다''는 조절 이력 ⑶ 인선 원칙(지시 이행형 선호). ⚠️ 맥긴·로저스 ''안쪽으로 들어온다''는 서술은 **obs#151과 충돌한다** — 우리 커널은 맥긴 RM의 인사이드 포워드 결론을 그리드로 기각했다. 서사가 위치 실측을 이기지 않는다는 규칙대로 obs#151을 유지하고, 이 서술은 ''온더볼 성향''(볼을 잡은 뒤 안쪽으로 몰고 들어감)으로 한정해 읽어야 한다 — 평균 위치가 안쪽이라는 뜻이 아니다. 캐시 수치는 3티어 블로그라 원자료 미확인.','2026-08-12');
INSERT INTO manager_profiles VALUES(1,'rotation',unistr('에메리의 로테이션은 ''유럽 대회 = 별도 팀''에 가깝다. 목요일(유로파)–일요일(리그) 사이클에서 유럽 경기에 후보군을 통째로 투입하고, 그중 잘한 선수를 리그 선발로 승격시키는 오디션 성격을 띤다. 25/26 유로파 리그 페이즈 개막전(볼로냐 1-0)에서 로저스를 제외한 거의 전원을 교체했고, GK는 마르티네스가 아닌 **비조(Bizot)** 가 선발, 파우 토레스가 밍스 대신, 마첸이 LB로 나섰다. 이후 리그 페이즈에서 게상·말렌·마첸·산초 등 후보군이 성과를 냈고(마카비 텔아비브 2-0은 마첸·말렌 득점), 에메리 스스로 이들의 리그 선발 기용을 시사했다. 컵 GK 분리(마르티네스=리그·큰 경기 / 비조=유로파)는 25/26 내내 유지된 패턴이다. 다만 이 방식은 실패 사례도 남겼다 — 유로파 준결승 국면에서 7명을 바꾼 라인업이 클럽 최악급 리그 경기력을 낸 적이 있고, 그 결정은 광범위한 비판을 받았다. 프리시즌에는 하프타임 10명 일괄 교체까지 쓴다(2026-08-01 인도네시아 올스타전).\u000a\u000a⚙️ **게임 구현**: 커리어 모드 운영 축이지 전술 세팅 축이 아니다. 반영한다면: 유로파/컵 경기 GK를 비조로 고정(마르티네스는 리그·토너먼트 큰 경기), 유로파 리그 페이즈에 마첸·말렌·산초·게상 계열을 선발로 돌리는 로테이션 프리셋. **역할 처방(prescriptions)은 바꾸지 않는다** — 인선 축이지 커널 축이 아니다.'),'AVillaFan, ''Emery makes BIG changes for Europa League opener''(25/26 리그 페이즈 개막) https://www.avillafan.com/39368/aston-villa-team-news-as-unai-emery-makes-huge-changes-for-europa-league-opener/ — 비조 선발·마르티네스 22인 명단 제외, 파우 토레스·마첸 투입, 로저스만 유지. Premier League 공식, ''What we learned from Aston Villa''s Europa League match'' https://www.premierleague.com/en/news/4426263/what-we-learned-from-aston-villas-europa-league-match — 게상·말렌·마첸·산초 4인 후보군의 활약과 리그 선발 시사. Fotmob 경기 리포트(마카비 텔아비브 2-0, 마첸·말렌 득점). Football365 — 유로파 준결승 전후 7명 교체가 최악의 리그 경기력으로 이어졌다는 비판. 우리 DB obs#126(2026-08-01 프리시즌 하프타임 10명 교체).',NULL,'MEDIUM. 개별 사례는 2~3티어 클럽 매체·PL 공식 혼재. **정량 표본 없음** — 시즌 전체 선발 변경 횟수·선수별 출전 시간 분포를 조회하지 않았다(FBref·Transfermarkt 미조회). 따라서 ''경기당 평균 N명 교체'' 같은 수치는 쓰지 말 것. 컵 GK 분리는 사례 2건 이상으로 확인. 준결승 7명 교체 건은 **24/25 시즌(포레스트전) 서술**로 보이나 발행 시점이 불명확해 시즌 귀속을 확정하지 못했다 — 25/26 사례로 쓰지 말 것.','2026-08-12');
INSERT INTO manager_profiles VALUES(1,'market',unistr('빌라의 이적 정책은 25/26 시즌 중 구조 자체가 바뀌었다. 2025년 9월, 개막 5경기 무승(강등권) 직후 몬치(Monchi)가 풋볼 오퍼레이션 회장직에서 물러났고 — 이유는 성적보다 **영입 적중률에 대한 의문** — 레알 소시에다드에서 이삭 영입·매각(£63m), 수비멘디 판매(£60m), 외데고르 임대를 성사시킨 **로베르토 올라베(Roberto Olabe)** 가 후임으로 왔다. 몬치 시절의 지배 변수는 PSR/UEFA 재정 규정이었고(몬치 스스로 4대 목표 중 1순위로 PSR 준수를 꼽았다), 그 결과 아카데미 출신 제이콥 램지 매각 같은 ''어쩔 수 없는 판매''와 마감일 임박 영입(산초·해비 엘리엇 임대, 린델뢰프 FA, 게상)이 반복됐다 — 에메리는 마감일까지 보강을 기다리며 공개적으로 불만이 커진 상태였다. 권한 분리는 명확하다: 에메리는 ''내 자리는 피치 위다, 밖의 일은 로베르토가 말하는 대로 따른다''며 올라베를 ''영입 전문가''로 규정했다(다만 올라베 선임 자체에 에메리가 관여했다). 성공 사례로 꼽히는 것은 모건 로저스와 자유계약 티엘레망스다. 26년 여름 우선순위는 **우측 윙어**로 보도되며, 판매로 먼저 여력을 만들어야 하는 구조는 그대로다.\u000a\u000a⚙️ **게임 구현**: 커리어 모드 운영 규칙으로: ⑴ 판매 선행 후 영입(예산 제약 재현), ⑵ 자유계약·임대를 적극 활용(티엘레망스·린델뢰프·산초 패턴), ⑶ 영입 프로필은 ''구조 안에서 지시를 이행하는 선수'' 우선 — 즉 능력치 총합보다 역할 커널 적합(fit_sim)이 높은 선수를 고르는 우리 방식과 정확히 같은 원칙이다. 전술 세팅에는 영향 없음.'),'BBC Sport, ''Aston Villa appoint Olabe as Monchi steps down'' https://feeds.bbci.co.uk/sport/football/articles/ce3ykg544l7o. Sky Sports, ''The key questions answered with Monchi replaced by Roberto Olabe'' https://www.skysports.com/football/news/11095/13436729/aston-villa-the-key-questions-answered-with-monchi-set-to-leave-villa-park — PSR 제약, 마감일 3영입, 에메리의 불만. The Athletic/Yahoo, ''Monchi left Aston Villa because of questions over his recruitment hit-rate''(2025-09) https://sports.yahoo.com/article/monchi-left-aston-villa-because-183000960.html — 로저스·티엘레망스 성공 / 전반적으로 ''기껏해야 절반''. Read Aston Villa(2026-06-15, BirminghamLive·El Diario Vasco 인용) https://readastonvilla.com/2026/06/15/emery-trusts-olabe-aston-villa-recruitment-2026/ — 에메리 인용 ''내 자리는 피치 위다''. Aston Villa News(2026-03-10) https://www.astonvillanews.co.uk/2026/03/10/who-roberto-olabe-has-on-transfer-wishlist-as-aston-villas-summer-priority-revealed/ — 26년 여름 우선순위 우측 윙어. Swiss Ramble, ''Aston Villa''s PSR Issues'' https://swissramble.substack.com/p/aston-villas-psr-issues — 재무 배경.',NULL,'MEDIUM-HIGH (구조 사실) / LOW (개별 링크). 몬치 퇴임·올라베 선임·PSR 제약·에메리의 권한 분리 발언은 1~2티어(BBC·Sky·The Athletic)로 확실하다. 반면 26년 여름 개별 타깃(페란 토레스·해리 윌슨·라시포드·트로사르 등)은 3티어 클럽 블로그·집계 매체라 **transfer_targets 등재 근거로 쓰기엔 부족**하다 — 우리 transfer-watch 절차의 교차검증을 거쳐야 한다. 에메리 발언의 원출처는 El Diario Vasco → BirminghamLive → 클럽 블로그의 3단 인용이라 표현 정확도에 여유를 둘 것.','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'pressing',unistr('【레버쿠젠 근거·1~2티어】 극단적 맨투맨 일변도가 아니라 혼성 압박이다. 기본은 5-2-3 중간블록이며, 상대 수비 3분의 1에서 맨투맨으로 점프해 백라인이 함께 전진, 라인 사이 공간을 지우고 상대를 롱볼로 몬다. 이때 오른쪽 윙백(프림퐁)이 상대 좌측 풀백으로 점프하고 RCB가 옆으로 벌려 덮으며 5-2-3이 4-2-4/4-4-2로 변형된다. 【레알 근거】 원리는 같되 4-4-2 기반의 상대 진영 맨투맨. 【수치】 레버쿠젠 23/24 하이턴오버(상대 진영 볼회수) 경기당 10.8회로 분데스리가 1위(참고: 마레스카 첼시 24/25는 7.8회 9위 — 알론소가 확연히 더 높은 압박 팀이다). 【점유가 압박을 먹인다】 초기 템포를 느리게 가져가 선수 간 거리를 좁힌 채 한 덩어리로 전진하고, 볼 상실 순간 상대 진영에서 질식시킨다 — 카운터프레스가 사실상 1차 수비선이다. 【알려진 약점】 레알에서 중간 3분의 1로 밀려 내려간 뒤에는 하이라인+맨투맨+전방 압박 강도 부족이 겹쳐 상대에게 이용당했다. 【첼시 근거】 프리시즌 1차전(웨스턴시드니)에서 볼 상실 시 4-4-2로 변형해 카운터프레스, 딜랍+사트파예프가 선봉. 다만 백라인 간격이 크게 노출됐다(신입·주전 미합류 상태). 첼시 공식전 표본 0.\u000a\u000a⚙️ **게임 구현**: 수비 접근 High + 라인 높이 상향은 지지된다(하이턴오버 1위). 단 ''중간블록에서 트리거로 점프''라는 성격상 Ultra-High보다 High가 정확. 전방 3인(2×10번+9번) 압박 포커스 상향, 윙백 중 우측은 압박 점프 담당이라 fb_att_wb/Attack 계열이 정합. 레알형 약점(중간 3분의 1로 밀린 뒤 취약)은 rest_defense 축의 기존 경고와 같은 원인이다.'),'Squawka ''Chelsea tactical analysis: How Xabi Alonso could set up the Blues''(2026, 검색 요약 경유 — 본문 403) · Alex Keble, Premier League 공식 ''Analysis: How will Chelsea look under Alonso?''(2026-07-22, premierleague.com/en/news/4677087) · Last Word on Sports ''Xabi Alonso Tactics Analysis for Chelsea Debut''(2026-07-28, lastwordonsports.com/football/2026/07/28/xabi-alonso-tactics/ — 본문 403, 검색 요약 경유)',NULL,'MEDIUM-HIGH — 하이턴오버 10.8(1위)은 PL 공식 매체(1티어)의 옵타 수치라 신뢰도 높음. 단 ⑴ 5-2-3 압박 구조는 레버쿠젠 근거이며 첼시 이식 미검증, ⑵ 첼시 근거는 프리시즌 1경기 관찰기(2티어)뿐, ⑶ 우리 DB obs#53의 ''레알 PPDA 10.8''과 여기의 ''하이턴오버 10.8''은 서로 다른 지표다 — 혼동 금지. ⑷ 첼시 25/26 실측(마레스카·로즈니어 체제)의 압박 수치는 알론소 근거가 아니다.','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'role_demands',unistr('포지션별 요구 (⚠️ 대부분 레버쿠젠·레알 근거, 첼시 인선 매핑은 예고 단계). 【백3】 볼 플레잉 CB 2명이 ''더 힘 있는 수비수'' 하나를 사이에 두고 배치된다(좌우 볼배급형 + 중앙 대인형). 요구 프로필은 1대1 강함·공중전·드리블 운반·정확한 롱패스이며, 위험한 시도보다 위치 단순함과 듀얼 승리를 요구한다(라크루아 영입 근거). 【윙백】 비대칭 — 한쪽은 전진해 폭을 독점하고 다른 쪽은 빌드업 시 안으로 접힌다. 크로서가 아니라 득점자다(레버쿠젠 23/24 프림퐁+그리말도 분데스 합계 19골 20도움). 첼시 대응: 퀜다·팔레스트라가 ''맞춤형''으로 지목됨. 【더블 피벗】 라인 사이로 패스를 꿰는 역할 + 운동능력·전술 지능·넓은 패스 범위(엔소·카이세도 지목). 레알에서는 추아메니를 CB 옆으로 내려 백4를 백3로 바꿨다 — 즉 피벗 한 명의 하강은 인원이 아니라 국면 조정 수단이다. 【2×10번】 미드필더와 함께 중앙에 ''사각형(box)'' 구조를 만들고 하프스페이스로 스며든다. 첼시 대응: 팔머=''유령처럼 침투하는 10번'', 로저스=''윙어/10번 하이브리드''이며 수비 가담 노동량이 명시적 요구다. 【9번】 내려오는 현대형 모바일 스트라이커(주앙 페드루). 【빌드업 원칙】 중앙에 인원을 몰아 수적 우위를 만들고 풀백/윙백이 폭을 담당한다.\u000a\u000a⚙️ **게임 구현**: cb_bpd 전원 일괄이 아니라 ''좌우 볼플레잉 2 + 중앙 대인형 1'' 분리가 더 정확 — CCB는 cb_stopper/cb_defender 계열 검토 가치가 있다(현 처방은 아다라비오요 cb_bpd/Build-Up). 윙백은 크로스형이 아니라 득점형이므로 Attack 포커스 유지. 2×10번의 수비 가담 요구는 로저스·팔머 포커스에서 Roaming보다 Balanced/Attack 쪽 근거가 된다.'),'Alex Keble, Premier League 공식(2026-07-22) · Rhys Desmond, TheMastermindSite ''How Xabi Alonso''s Chelsea could look in 2026-27''(2026-07-26) · Joana Freitas, Tactical Football Analysis(2026-05-28, 중간부 유료벽) · Squawka(검색 요약 경유)',NULL,'MEDIUM — 역할 원형은 1~2티어에서 일관되게 반복돼 신뢰 가능. 다만 첼시 선수 매핑은 전부 개막 전 예측(알론소 본인 발언 아님)이고, 프리시즌 실제 배치는 예측과 어긋난 지점이 있다(팔머가 오른쪽이 아니라 중앙 10번으로 밀란전 선발). 로저스는 obs#59의 1티어 알론소 직접 지시(포켓·9번 근처)와 정합.','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'situational',unistr('【첼시 근거·1티어(본인 발언)】 알론소는 밀란 3-0 승리(2026-08-08, 인도네시아 슈퍼컵) 뒤 시스템관을 직접 밝혔다: "우리는 접근과 시스템에서 다재다능하길 원한다", "시스템은 한 장의 사진일 뿐이다 — 움직이고 회전하며 역동성을 만들어야 그 사진이 영화가 된다", "우리는 하나의 아이디어에만 매달리지 않는다. 선택지가 많을수록 더 좋은 팀이 된다." 즉 백3/백4를 상대에 따라 오가는 것이 선언된 방침이며, 포메이션보다 움직임·회전·선수 간 관계를 우선한다. 【레버쿠젠 근거】 포메이션은 경기별 도구였다 — 뮌헨 3-0 승(2024-02)에서는 점유율 39%로 내려앉아 역습으로 처리했고, 2025-02 뮌헨 원정 0-0에서는 그 경기용으로 설계한 4-2-2-2를 썼다(상대의 68분 4명 교체·구조 변경에도 뚫리지 않음). 리드 보호 시에는 볼 상실 후 컴팩트한 중간블록으로 내려앉아 상대를 끌어들인 뒤 역습한다. 【늦은 골】 23/24 추가시간 골 19개·리그 경기당 2.6골·51경기 무패의 ''레버쿠젠 후반'' 현상에 대해 본인은 훈련하거나 조작할 수 있는 것이 아니라 "팀의 멘털리티"라고 일축했고, 오히려 경기 운영이 컴팩트하지 못하고 수동적인 구간이 있었다며 더 공격적이길 요구했다 — 즉 늦은 골은 설계가 아니라 부산물이라는 것이 본인 입장이다. 【레알 반례】 이식은 아틀레티코 패배(9월)를 분기점으로 역행했다(obs#55) — 상황 대응력이 항상 성공한 것은 아니다.\u000a\u000a⚙️ **게임 구현**: ''하나의 포메이션 처방''이 알론소의 자기 선언과 충돌한다 — FC26에서는 기본 5-4-1(또는 3-4-2-1) + 상대별 대체 4-2-3-1 프리셋 2벌 운용이 원의도에 더 가깝다. 리드 시 수비 접근을 High→Balanced로 내리고 중간블록 유인 후 역습이 레버쿠젠 실제 운용과 정합.'),'알론소 밀란전 후 발언 — 첼시 공식 경유 OneFootball(2026-08-08, onefootball.com/en/news/what-xabi-alonso-revealed-about-chelseas-formation-after-ac-milan-win-43249138) · Get German Football News ''Leverkusen-Bayern tactical analysis''(2025) · Soccerway/Flashscore ''Alonso wants Leverkusen to be more aggressive after snatching late win''(알론소 직접 발언)',NULL,'HIGH(발언 부분) — 첼시 부임 후 본인 1차 발언이라 이 축에서 가장 강한 근거다. MEDIUM(구현 부분) — 실제로 상대별로 어떻게 바꾸는지는 공식전 0경기라 미검증. ⚠️ 우리 DB의 3-4-2-1 고정 처방은 이 발언과 긴장 관계에 있다(단일 포메이션 전제).','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'set_pieces',unistr('【첼시 근거·1~2티어 · 이 축에서 부임 후 가장 큰 실제 변화】 알론소는 첼시 코칭스태프를 짜며 오스틴 맥피를 세트피스 코치로 아스톤 빌라에서 영입했다(2026-07 발표, 공식 스태프 명단 2026-08-05). 기존 세트피스 코치 베르나르도 쿠에바는 테크니컬 애널리스트로 이동. ⚠️ 이는 우리 프로젝트의 다른 대상 팀(에메리·빌라)에서 사람을 빼온 것이다 — 빌라 세트피스 우위의 인적 원천이 첼시로 옮겨졌다. 【영입 근거 수치】 첼시는 지난 시즌 PL 논페널티 세트피스 득점 10위였고, 실점은 리버풀·본머스·팰리스만이 더 많았다(즉 세트피스 수비가 리그 최하위권). 빌라는 지난 시즌 PL 세트피스 18골(공동 4위)로 첼시보다 5골 많았다. 【맥피 방법론】 최장신을 골에어리어에 세우는 식이 아니라, 움직임으로 상대를 조작하고 배달을 위장하며 계획된 블록을 쓴다. 로저스가 리버풀전에 넣은 코너 루틴을 설계한 것이 맥피다(그 로저스가 지금 첼시에 있다). 첼시 내 표적: 토신 아다라비오요가 높이를 대고, 콜윌·라크루아는 깊은 출발점에서 달려든다. 【레버쿠젠 근거】 세트피스는 세바스티안 파리야가 담당했고 분데스리가 코너 득점 1위였다 — 그 파리야가 첼시 어시스턴트 코치로 함께 왔다. 루틴 테마: 공중전이 약한 비르츠를 오히려 표적 선수의 마커를 막는 스크린/블로커로 사용(그가 마크되지 않는다는 점을 역이용), 존 수비 라인 뒤 공간 공략, 숏코너 적극 활용. 【프리시즌 산출】 밀란전 3골 중 2골이 코너에서 나왔다(주앙 페드루 헤더 — 카이세도 코너 / 카이세도 아웃프런트 발리 — 라비아 코너).\u000a\u000a⚙️ **게임 구현**: FC26에는 세트피스 코치 축이 없어 직접 대응 슬롯은 없다. 다만 ⑴ 코너 키커는 카이세도·라비아(프리시즌 실측 도우미 2건) — 팔머 고정 전제를 재검토, ⑵ 세트피스 표적 프로필로 아다라비오요·라크루아의 출전 가치가 상향, ⑶ 빌라(에메리) 비교 축에서 ''세트피스 우위=빌라''라는 전제가 26/27에는 흔들린다.'),'Training Ground Guru ''Chelsea confirm MacPhee as Set Piece Coach as Alonso names staff''(2026-08-05, trainingground.guru) · Yahoo Sports ''Chelsea poach set-piece guru MacPhee from Aston Villa'' · Read Chelsea ''What Austin MacPhee will bring to Chelsea under Xabi Alonso''(2026-07-25, 본문 403·검색 요약 경유) · Total Football Analysis ''Xabi Alonso Set-Piece Tactics At Bayer Leverkusen 2024/25'' · 첼시 공식 매치리포트 Chelsea 3-0 Milan(2026-08-08)',NULL,'HIGH(스태프 인사·수치) — 스태프 명단은 1티어 전문 매체, 세트피스 득실 순위는 옵타 계열 수치. MEDIUM(루틴 내용) — 맥피·파리야의 구체 루틴은 2~3티어 서술이며 첼시에서의 실제 루틴은 공식전 0경기로 미확인. ⚠️ 기존 DB obs#49(''세트피스는 설계된 무기'')를 갱신하는 것이 아니라, 담당자가 파리야+맥피 2인 체제로 바뀐 새 사실이다.','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'rotation',unistr('【첼시 근거·1티어 본인 발언 포함】 알론소는 41~46명까지 불어난 1군 명단을 물려받았고, 약 25명 규모로 줄이려 한다고 보도됐다(9월 전 약 16명 방출·임대 필요). 스쿼드 크기 질문에 본인은 숫자를 못 박지 않았다: "너무 길지도, 너무 짧지도 않게 — 그 숫자가 뭐냐고? 나는 그 숫자를 줄 수 없다." 최우선 순위는 부상 사태 회피이며 포지션별 복수 옵션은 타협 불가라는 입장. 【구조 조건】 26/27 첼시는 유럽대회가 없다 — PL·FA컵·리그컵뿐이므로 경기 수가 적고 로테이션 압력이 낮으며, 알론소 본인이 자기 전술을 심을 시간이 많다(다수 매체 공통 지적). 【프리시즌 실운용】 GK를 45분씩 균등 분할했다(산체스/펜더스) — 밀란전은 산체스 90분, 다음 날 조호르전은 펜더스 예정. 24시간 간격 2연전(밀란 8/8 → 조호르 8/9)에서는 어린 선수를 대거 기용했고 "내일 계획은 이미 어제 짜여 있었다"며 이틀 연속 경기는 "상당히 힘들다"고 말했다. 밀란전 교체는 59분 2명·79분 1명·85분 3명으로 후반 집중형. 【실제 정리】 이미 완료된 유출: 쿠쿠레야(레알 마드리드), 안드레이 산투스, 티리크 조지(에버턴 완전이적), 임대 가르나초·제시 데리·켄드리 파에스. ⚠️ 참고 조건: ''봄스쿼드''(1군과 분리 훈련) 방식은 FIFA가 금지해 방출 아니면 임대 외 선택지가 없다.\u000a\u000a⚙️ **게임 구현**: 커리어 모드 기준: 유럽대회 없음 → 주중 경기 부재 → 로테이션 최소화·주전 고정이 원의도에 가깝다. 스쿼드 25명 목표는 대규모 방출 시나리오와 정합. GK는 산체스 1옵션이되 펜더스가 실제 경쟁자로 격상됐다(현 처방은 산체스 gk_ballplaying/Build-Up 고정).'),'Sports Mole ''We need to be prepared: Alonso plays down perception over size of Chelsea squad''(2026, 알론소 직접 인용) · BBC 경유 보도(스쿼드 25명 목표·16명 정리) · chelsea.news ''Chelsea squad: Alonso faces 46-player selection task''(2026-08) · Read Chelsea ''Chelsea vs AC Milan: Alonso faces difficult call before 24-hour turnaround''(2026-08-08, 알론소 조호르전 발언) · 첼시 공식 매치리포트(2026-08-08)',NULL,'MEDIUM-HIGH — 알론소 직접 발언과 유럽대회 부재는 사실 확정. 스쿼드 목표 인원(25명)·방출 16명은 보도 기반 추정치이며 이적시장 마감(9월) 전까지 유동적. GK 45분 분할·후반 집중 교체는 프리시즌 관행이라 시즌 운용으로 일반화 금지.','2026-08-12');
INSERT INTO manager_profiles VALUES(2,'market',unistr('【첼시 근거·2026 여름 실제 창구】 IN: 모건 로저스(빌라, 약 £117m/€138m — 엔소 £103m을 넘긴 구단 최고액 경신), 마르코 팔레스트라(아탈란타, 약 £43m — 알론소 부임 후 첫 영입, 7/1 완료, 21세 양쪽 측면 가능), 제오바니 퀜다(스포르팅, 약 €50m — 2025-03 선합의분, 19세, 전진 윙 또는 윙백 겸용), 막상스 라크루아(크리스털 팰리스, 약 £52m — 셰프 스털링 이후 첼시가 처음으로 26세 초과 선수에게 이적료를 쓴 사례로, 팰리스의 컨퍼런스리그 우승 백3에서 검증), 에마뉘엘 에메가(스트라스부르, 약 €25m), 페프 차바리아(라요 바예카노, 약 £16.3m/€21m — 8/6 합의, 28세 좌측 풀백으로 쿠쿠레야 이탈 보전이며 알론소가 직접 강하게 밀었고 좌측 1옵션 구상), 대니 웰벡(브라이턴, 약 €6m), 조던 헨더슨(자유계약), 데네르, 다스탄 사트파예프. OUT: 쿠쿠레야(레알 마드리드, 약 €60m — 선수 주도), 안드레이 산투스, 가르나초(임대), 티리크 조지(에버턴), 니콜라스 잭슨 임대 복귀 예정. 【읽히는 방침】 ⑴ 나이 곡선 상향 — 라크루아·차바리아·웰벡·헨더슨으로 ''드레싱룸의 안정된 목소리''와 즉시전력을 보강(첼시의 기존 초저연령 대량구매 기조에서의 이탈), ⑵ 다포지션 겸용 선호 — 팔레스트라·퀜다·로저스 모두 ''여러 위치·역할 수행''이 명시 근거이며 이는 situational 축의 가변 시스템 선언과 직결, ⑶ 백3에서 검증된 CB(라크루아)와 좌우 겸용 측면(팔레스트라)이라는 구조적 보강, ⑷ 팔머·주앙 페드루는 매각 불가로 타 구단에 통보. ⚠️ 로저스는 우리 프로젝트 대상 팀 간 이동이다(에메리 빌라 → 알론소 첼시) — 빌라 실측 자산이 첼시 축으로 넘어갔다.\u000a\u000a⚙️ **게임 구현**: 커리어 모드 스쿼드 갱신 필요: 차바리아 LB 1옵션 추가(현 처방은 좌 윙백 인선 공백으로 아토 지정 — 재검토 필요), 라크루아 CB 추가(밀란전 미출전, 합류 대기), 팔레스트라·퀜다는 양쪽 겸용 등록. 로저스는 빌라 스쿼드에서 제거해야 한다.'),'TeamTalk/OneFootball ''Every completed Chelsea transfer in summer 2026: Signings, sales, loans'' · 첼시 공식 ''Summer transfers 2026: All the Chelsea ins, outs and new contracts so far'' · BBC ''Chelsea sign Quenda and Essugo for combined £62.4m'' · Fabrizio Romano 경유 Football365(차바리아, 2026-08-06 "here we go") · Last Word on Sports ''Chelsea Close In on Signing New Left Back for £21 Million''(2026-08-02) · TheMastermindSite(2026-07-26, 웰벡·헨더슨 역할 해석)',NULL,'MEDIUM-HIGH — 완료 이적은 다수 매체 교차 확인. 단 ⑴ 금액은 매체별로 파운드/유로 환산이 엇갈린다(로저스 £117m vs €138m 등), ⑵ 사전 합의분(퀜다·에메가)은 알론소 취향이 아니라 클럽 정책 산물이므로 ''알론소 영입''으로 귀속 금지 — 알론소 귀속이 명시된 것은 팔레스트라(첫 영입)와 차바리아(직접 요청)뿐, ⑶ 창구는 9월 마감 전이라 변동 가능.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'formation',unistr('기본형은 소유 4-2-3-1 / 무소유 4-4-2의 이중 셸이며, 리버풀에서도 이 틀을 그대로 가져간다. [본머스] 저위치 빌드업에서는 6번 1명 + 8번 2명의 4-3-3으로 갈라졌다가 전방 투입 시 4-2-4로 늘어나고, 고위치에서는 8번 둘을 최전방 라인에 붙여 4-1-5에 가까워진다. 상황에 따라 4-4-2 다이아몬드, 잔여수비 국면에서는 3-2-3-2도 나타난다. 즉 ''고정 포메이션''이 아니라 국면별로 갈아입는 형태이고, 무소유 셰이프는 상대 미드필더 움직임을 따라 전방 2명이 순간적으로 콤팩트한 3명으로 바뀌는 등 계속 변한다. [리버풀] 프리시즌 3경기(7/25 선덜랜드 4-2 승 내슈빌, 렉섬전 승, 리즈전, 안필드 데뷔전 모나코전 2-0 리드 후 2-3 패)에서도 4-2-3-1이 골격. 매체는 ''슬롯이 지난 시즌 후반 쓴 셰이프와 같아 복귀 선수들에게 익숙하다''는 점을 이식 이점으로 본다. 본인 발언은 셰이프가 아니라 원칙 중심이다 — ''열심히 뛰고, 강도 높고, 공격적이고, 수직적인 팀''.\u000a\u000a⚙️ **게임 구현**: FC26 팀 세팅은 4-2-3-1 유지가 맞다(프로젝트 11슬롯 매핑도 그대로 유효). 다만 ''고정 포메이션''으로 다루면 원형을 놓친다 — 소유 시 풀백 전진 + 8번 2명 고위치가 4-1-5에 가까워지는 것을 커스텀 지시(풀백 Attack/Overlap, 미드 2명 중 1명만 Hold)로 근사해야 한다.'),'Alex Keble, 프리미어리그 공식 ''Analysis: How will Liverpool look under Iraola?'' 2026-06-04 (https://www.premierleague.com/en/news/4673093/analysis-how-will-liverpool-look-under-iraola) · Vedant Kharakwal, Tactical Football Analysis 2026-06-04 (https://tacticalfootballanalysis.com/andoni-iraola-tactics-liverpool-2026-2027-tactical-analysis/) · The Football Analyst 2024-05-12 (https://the-footballanalyst.com/andoni-iraola-afc-bournemouth-tactical-analysis/) · 리버풀 공식 ''이라올라 첫 기자회견 전문'' 2026-07-13 (https://www.liverpoolfc.com/news/every-word-andoni-iraolas-first-press-conference-liverpool) · Alvino Hanafi, Goal.com 2026-08-11 (https://www.goal.com/en/lists/liverpool-andoni-iraola-2026-27-premier-league/blt2d70dc0df5b54109) · 유튜브 The Overlap ''How Andoni Iraola Is Already Changing Liverpool'' 2026-08월 초 (https://www.youtube.com/watch?v=CKp3tq-Qs1w) — 영상 미시청, 검색 요약 근거',NULL,'MEDIUM-HIGH — 국면별 셰이프(4-3-3/4-2-4/4-1-5/4-4-2)는 본머스 1~2티어 다수 매체가 일치. 리버풀 4-2-3-1은 프리시즌 관측·예측이며 공식전 검증 0. 유튜브 영상은 미시청으로 근거 채택하지 않았고 URL만 기록.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'buildup',unistr('점유는 목적이 아니라 부산물이다 — [본머스] 평균 점유 47.5~50%, 시퀀스당 패스 3.0. 저위치에서 빠르고 수직적인 롱볼을 정상 수단으로 쓴다: 센터백 둘이 골키퍼 앞에서 좁게 갈라지고 풀백은 중앙 미드필더 높이까지 올려 뒤에 6명을 남긴 채 상대를 끌어들인 뒤, 전방 4명을 향해 길게 때린다. 8번 둘을 높게, 공격수를 중앙에 모아두는 배치는 세컨드볼 회수를 노린 설계다. 골키퍼가 항상 기점은 아니다 — 한 경기에서는 GK를 거치지 않고 센터백에서 아주 넓게 벌린 풀백으로 붙여 압박 이동거리를 늘린 뒤 풀백이 무압박 롱볼을 때렸는데, 필요가 아니라 의도된 수단이었다. 배후 침투를 상시 유지해 상대가 하이라인을 유지하지 못하게 만들고, 그렇게 열린 라인 사이 공간으로 8번을 찾는 것이 고위치 빌드업의 핵심. 6번은 필요할 때만 내려오고 원칙은 ''가능하면 항상 빠른 전진 패스''. [리버풀] 이라올라 본인이 프리시즌에 밝힌 소유 목표는 지역이다 — ''공을 갖고도, 갖지 않고도 상대 진영에서 최대한 오래 보내고 싶다''. 프리시즌 관측도 느리고 층진 빌드업에서 빠른 볼 이동으로 바뀌었다는 쪽.\u000a\u000a⚙️ **게임 구현**: FC26 빌드업 스타일은 Balanced보다 Counter/Direct 쪽 검토가 근거를 얻었다(시퀀스당 3.0패스·의도적 롱볼). 다만 ''롱볼 축구''가 아니라 ''세컨드볼 설계가 딸린 롱볼''이므로 전방 밀집(8번 2명 고위치)이 동반되지 않으면 게임에서 그냥 손실이 된다. GK 빌드업 관여는 낮게.'),'Alex Keble, 프리미어리그 공식 2026-06-04 (점유 47.5%·시퀀스당 3.0패스) · The Football Analyst 2024-05-12 (저위치 4-3-3·고위치 4-1-5·GK 우회 롱볼) · Tactical Football Analysis 2026-06-04 (더블피벗 기본·필요시 싱글피벗, 경기당 13.8슈팅/4.7유효) · 리버풀 공식 첫 기자회견 전문 2026-07-13 (본인 발언)',NULL,'MEDIUM-HIGH — 본머스 빌드업 서술은 1~2티어 3개 매체가 서로 어긋나지 않는다. 리버풀 이식은 본인 발언 1차 자료 + 프리시즌 관측뿐. ⚠️ 최대 미해결 쟁점: 리버풀은 구조적으로 점유가 높은 팀인데(클롭기 61.7%) 이라올라 시스템은 저점유에서 작동했다 — obs#146/situational 축의 지배 국면 리스크와 같은 문제.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'role_demands',unistr('포지션별 요구가 명시적이고 수비 우선이다. [풀백] 높게 압박하면서 넓은 공간을 1대1로 지킬 체력·민첩성. 케르케즈 본인 증언 — 이라올라는 항상 ''풀백은 먼저 강하게 수비해야 하고 앞에서 하는 모든 것은 보너스''라고 말했고, 자기 몫을 다한 뒤에야 표현의 자유가 주어졌다. 라인을 따라 내려가는 오버랩·언더랩을 선호하며 낮고 빠른 얼리크로스의 공급원(기존 obs#67). [센터백] 스트라이커를 미드필드 20m까지 따라 올라가 그 자리에서 경합하는 것을 편하게 여겨야 한다 — 전방 수비가 본업이다. 하이라인 때문에 1대1로 버티는 능력이 채용 기준이 된다. [6번] ''탈취 즉시 전진 패스''가 가능한 볼위너. Opta는 이라올라가 ''기술형 1명 + 파괴형 1명''의 더블피벗을 선호한다고 정리했다. [8번] 6번과 같은 속도의 판단, 라인 사이 포켓 점유와 하프스페이스 언더랩. [윙어] 직선적으로 달리되 ''첫 임무는 압박''. 양발/양측면 소화를 요구한다 — 이라올라는 프리시즌에 응구모하를 두고 양쪽 다 뛰는 윙어를 키우는 것이 자기 철학이며 출전 기회와 전술적 유연성을 늘린다고 직접 말했다. [9번] 필드를 반으로 갈라 패스 길을 끊는 압박 각도가 첫 임무. [10번] 비르츠를 스트라이커 뒤 공격형 미드필더로 쓰겠다고 명시했고 ''공 없을 때의 강도 높은 활동량''을 적합 근거로 들었다.\u000a\u000a⚙️ **게임 구현**: 슬롯 매핑 재검토 근거가 생겼다 — 풀백은 fb_att_wb(Support)보다 수비 기여를 요구하는 설정이 원형에 가깝고, CB는 cb_bpd/Aggressive 유지가 맞다(전방 추격 요구와 일치). 윙어는 양측면 소화 요구가 있어 특정 발 고정형 배치를 피할 것. 비르츠는 cam(10번) 고정이 감독 발언으로 확정에 가깝다.'),'Coach Notes ''Andoni Iraola Tactics and Coaching Style Analysis'' 게시일 미상(2026-06 이후) (https://coachnotes.co.uk/blogs/coaching-analysis/andoni-iraola) · 케르케즈 인터뷰 ''Iraola is the perfect fit for us'' 2026 (https://www.aol.com/articles/iraola-perfect-fit-us-kerkez-122831000.html) · 리버풀 공식 시카고 기자회견 2026-07-30 (비르츠·응구모하 발언) (https://www.liverpoolfc.com/news/andoni-iraola-press-conference-chicago-benefits-ngumoha-and-wirtz-positions-transfers-and-more) · David Segar, Opta Analyst 2026-08-11 (더블피벗 구성) (https://theanalyst.com/articles/liverpool-squad-audit-transfers-stats-2026-27) · Tactical Football Analysis 2026-06-04',NULL,'MEDIUM-HIGH — 풀백·비르츠·응구모하 항목은 1차 자료(선수 본인·감독 본인 발언). 센터백·6번·윙어 항목은 2~3티어 코칭 분석이나 우리 DB obs#68/69와 독립적으로 일치한다. 게시일 미상 소스 1건 포함.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'rest_defense',unistr('공격 시 5명 투입 / 5명 잔류가 규약이고, 잔류 5명은 3-2-3-2에 가까운 잔여 셰이프를 만든다. 이 배치가 즉시 역압박의 발판이며, 우리 DB obs#72(하이프레스의 통상적 대가인 역습 피허용이 발생하지 않았다)의 구조적 설명에 해당한다. 저압박 국면에서는 4-4-2 미드블록으로 내려앉아 상대 패스 한 번마다 전진해 필드를 계속 압축한다. 중앙에 인원을 모아두는 설계 덕에 소유를 빠르게 회수하고, 그 회수를 곧장 전방 전환으로 잇는다. 훈련 자체가 ''공보다 공 주변의 순간''을 다룬다 — 탈취 후 5초 내 역습, 콤팩트 간격, 압박 트리거가 훈련 단위다. ⚠️ [리버풀] 프리시즌에서 이 부분이 아직 안 잡혔다: 안필드 데뷔전에서 2-0 리드를 2-3으로 뒤집혔고, 매체는 풀백 전진이 수비 라인을 노출시키는데 센터백들의 경기 감각이 부족하다는 점을 원인으로 지목했다. 이라올라 본인도 ''이렇게 뛰기 위해 요구되는 수준에서 우리에겐 더 여유가 없다''며 체력 문제를 인정했다(개막 2주 전).\u000a\u000a⚙️ **게임 구현**: FC26에서 잔여수비 5명은 ''풀백 둘 동시 전진 금지''로 번역된다 — obs#81(본머스 풀백은 double threat이 아니다)과 정확히 같은 결론이며, 한쪽 풀백만 Attack/다른 쪽 Balanced 이하가 원형이다. 역압박은 Counter Press 계열 지시로 근사.'),'thisisanfield ''Andoni Iraola tactics: How Liverpool could play'' 2026-06 (5-5 분할·3-2-3-2 잔여 셰이프, 본문 접근 403 — 검색 인덱스 요약 근거) (https://www.thisisanfield.com/2026/06/andoni-iraola-tactics-liverpool-fc/) · Tactical Football Analysis 2026-06-04 (5명 투입 후 5명 수비 형성) · The Football Analyst 2024-05-12 (4-4-2 미드블록·중앙 밀집 전환) · Coach Notes (5초 역습 훈련) · Richard Jolly, The Independent 2026-08-09 (모나코전 2-0→2-3, 풀백 전진 노출·이라올라 체력 발언) (https://sports.yahoo.com/articles/problem-liverpool-must-address-andoni-160834064.html)',NULL,'MEDIUM — 3-2-3-2 잔여 셰이프는 2개 매체가 독립적으로 같은 수치(5-5)를 말하나 한 곳은 본문 접근 실패로 검색 요약 근거다. 리버풀 붕괴 사례는 친선경기 1건이므로 추세로 쓰면 안 된다.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'set_pieces',unistr('세트피스는 훈련 시간을 정식으로 배정받는 항목이고, 본머스 공격 루틴은 리그에서 손꼽히게 창의적이라는 평을 받았다 — 우리 DB obs#74가 기록한 ''최대 결함은 세트피스 수비''와 모순이 아니라 공수 비대칭이다(공격 루틴은 강점, 수비가 약점). [리버풀] 이라올라는 코치진 역할을 명시적으로 분업했다: 토미 엘픽이 수비 세트플레이, 션 쿠퍼가 공격·창의적 루틴을 맡는다. 둘 다 본머스에서 함께 온 인력이다. 여기에 구단에 원래 있던 세트피스 분석가 루이스 마호니를 유임시켜 신규 코치진과 함께 일하게 했다 — 지난 시즌 후반 인상적이었다는 이유. 이 배치는 문제 인식에서 나온 것으로 보인다: 리버풀은 25/26에 세트피스로 23골을 내줘 뉴캐슬·웨스트햄과 함께 리그 공동 3위로 나빴다. 즉 이라올라의 본머스 약점(세트피스 수비)과 리버풀의 기존 약점이 같은 지점에서 겹치며, 대응으로 전담 수비 세트피스 코치를 별도로 세운 것이 그의 첫 구조적 조치다.\u000a\u000a⚙️ **게임 구현**: 직접적 FC 세팅 함의는 약하다(게임 내 세트피스는 팀 세팅으로 재현 불가). 다만 ''수비 세트피스가 이 체제의 알려진 구멍''이라는 사실은 게임에서 코너 수비 인원 배치를 보수적으로 두는 근거가 된다.'),'ESPN ''Andoni Iraola breaks down Liverpool backroom staff revamp'' 2026 (엘픽=수비 세트플레이 / 쿠퍼=공격, 마호니 유임, 이라올라 직접 발언) (https://www.espn.com/soccer/story/_/id/49435815/andoni-iraola-breaks-liverpool-backroom-staff-revamp) · liverpool.com 코치진 확정 기사 (https://www.liverpool.com/liverpool-fc-news/features/andoni-iraola-backroom-staff-liverpool-34222096) · Coach Notes (본머스 루틴 창의성 평) · 리버풀 25/26 세트피스 23실점(리그 공동 3위 최악) — ESPN 기사 내 인용',NULL,'MEDIUM-HIGH — 코치 분업은 감독 본인 발언 인용의 1차 자료. 단 일부 매체(더 타임스 폴 조이스)는 쿠퍼를 세트피스 코치, 데 라 토레를 피지컬 코치로 보도해 구단 공식 직함과 어긋난다 — 직함 표기는 구단 공식을 채택. 23실점 수치는 원 출처 재확인 필요.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'rotation',unistr('이라올라는 스쿼드 폭을 전술적 필수 조건으로 본다 — 첫 기자회견에서 ''이런 시즌을 13, 14, 15명으로 감당하는 것은 불가능하고 스쿼드 전원이 필요하다''고 직접 말했다. 월드컵 참가로 선수들이 시차를 두고 복귀한 것도 부정적으로 보지 않았다: 선수 개개인과 더 접촉할 시간이 생기고 아카데미 선수에게 기회를 준다는 것. 시카고 프리시즌에서도 ''이전에 알지 못했던 어린 선수들이 매우 높은 수준으로 놀라게 했다''고 했고, 판 다이크·고메스 결장으로 센터백이 얇아지자 18세 은디아예·은두케를 실전에 넣고 침착함을 칭찬했다. 개막전 운용도 명시했다 — 뉴캐슬전에 같은 11명을 그대로 쓰는 것은 좋지 않고 확실히 선수를 회복시킬 것이며 월드컵 복귀 선수들이 포함된다. 맥 알리스터는 프리시즌 합류가 늦어 개막 몇 주간 선발이 어렵다고 본인이 이미 시사했다. 로테이션의 근거는 조직 우선 철학과도 맞물린다 — 본머스는 최고 선수들을 계속 팔고도(24년 여름 하위센·자바르니·케르케즈 £147m 유출, 25/26 겨울 세메뉴 매각) 시스템 산출이 유지됐고 18경기 무패로 끝냈다(우리 DB obs#76과 동일 논지). 체력을 전술 요건으로 다루며 스포츠과학자 파블로 데 라 토레를 어시스턴트 코치로 데려왔다.\u000a\u000a⚙️ **게임 구현**: FC26 커리어/시즌 운용 함의 — 특정 11명 고정보다 폭넓은 기용이 원형에 맞다. 다만 게임 재현의 실질 변수는 아니므로 우선순위는 낮다.'),'리버풀 공식 첫 기자회견 전문 2026-07-13 (스쿼드 전원 필요·월드컵 시차 복귀 발언) · 리버풀 공식 시카고 기자회견 2026-07-30 (은디아예·은두케 기용, 유망주 평) · 검색 인덱스 요약된 개막전 로테이션 발언(뉴캐슬전 동일 11 배제) — liverpoolfc.com 기자회견 기사 계열 · Coach Notes (시스템의 선수 의존도·데 라 토레 역할) · worldsoccertalk 맥 알리스터 관련 (https://worldsoccertalk.com/news/andoni-iraola-addresses-alexis-mac-allisters-liverpool-future-after-great-2026-world-cup-performance/)',NULL,'MEDIUM-HIGH — 대부분 감독 본인 발언(1차 자료). 개막전 로테이션 발언은 검색 요약 경유라 전문 재확인 권장. ⚠️ 로테이션 ''실행''은 공식전 0경기라 검증 불가 — 현재는 선언 단계다.','2026-08-12');
INSERT INTO manager_profiles VALUES(3,'market',unistr('영입 프로필이 전술 요구에서 직접 파생된다. 핵심 축은 (1) 하이라인을 감당할 속도·경합력 있는 센터백, (2) 1대1 수비가 되는 풀백, (3) ''기술형 + 파괴형'' 더블피벗의 파괴형, (4) 압박 가담이 되는 직선적 윙어. 26년 여름 리버풀 실행: 제레미 자케(렌, £55m+£5m, 20세 — 하이라인에 맞는 운동능력이 명시적 채용 사유), 로날드 아라우호(바르셀로나 임대, 매입옵션 €55m — 이라올라가 FSG에 센터백 보강을 요구했고 판 다이크에게 의견을 물었다는 보도), 빅토르 무뇨스(6월). 유출은 코나테(레알 마드리드)·살라. Opta 스쿼드 감사(8/11)는 남은 결손을 이렇게 정리했다 — 최우선은 공격진(살라의 우측 윙 대체가 없음, 이시크의 백업 스트라이커 부재, 하포 이탈 가능), 그다음 전문 수비형 미드필더 부재(엔도는 정기 선발 수준에 못 미친다는 평), 센터백 뎁스(판 다이크 35세·지난 시즌 55경기+월드컵으로 과부하), 우측 풀백(프림퐁 잦은 부상·브래들리 회복 불투명). 제약은 비홈그로운 등록 17명 상한이라 추가 영입에 방출이 선행돼야 한다. 남은 타깃으로는 브래들리 바르콜라(PSG, 측면 1순위)·구엘라 두에가 거론되고 얀 디오망데는 놓쳤다. 이라올라 본인은 8월 시장을 싫어한다고 밝혔다 — 9월 1일 마감 이후에야 스쿼드 정체성을 확정할 수 있다는 이유이며, 두 명이 왔지만 더 필요하다고 인정했다.\u000a\u000a⚙️ **게임 구현**: 스쿼드 슬롯 재산출 필요. 특히 우측 윙(살라 부재)과 전문 DM 부재는 게임에서 슬롯 공백으로 그대로 나타난다 — 현재 DB의 wm_winger/살라, cb_bpd/코나테 매핑은 26/27 기준으로 무효 가능성이 높다.'),'David Segar, Opta Analyst ''Liverpool 2026-27 Squad Audit'' 2026-08-11 · Goal.com, Alvino Hanafi 2026-08-11 (자케·아라우호·바르콜라·두에) · Richard Jolly, The Independent 2026-08-09 (살라 대체 공백·CB 뎁스) · 리버풀 공식 시카고 기자회견 2026-07-30 (8월 시장 관련 본인 발언) · 리버풀 공식 첫 기자회견 2026-07-13 (두 명 영입·더 필요 발언) · teamtalk 아라우호 관련 (https://www.teamtalk.com/liverpool/barcelona-liverpool-ronald-araujo-virgil-van-dijk-andoni-iraola)',NULL,'MEDIUM — 확정 거래(자케·아라우호)와 감독 발언은 신뢰 가능. 타깃·이유 서술(FSG에 요구, 판 다이크에게 의견) 및 이적 루머성 항목은 2~3티어이며 우리 transfer_targets 등급 절차로 별도 검증 필요. ⚠️ 살라·코나테 이탈은 우리 DB squad_entries(regime_id=3)와 충돌 — obs 후보로 분리했다.','2026-08-12');
